	`requested_network_mode` text NOT NULL,
	`currency` text,
	`upper_minor` integer,
	`estimate_high_minor` integer,
	`customer_payable_minor` integer NOT NULL,
	`status` text NOT NULL,
	`sampling_complete` integer NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "monitoring_run_scope_check" CHECK("monitoring_run"."track" in ('model_api', 'consumer_ui')
    and "monitoring_run"."repeat_count" between 1 and 3
    and "monitoring_run"."question_count" > 0 and "monitoring_run"."natural_count" between 0 and "monitoring_run"."question_count"
    and "monitoring_run"."channel_count" > 0 and "monitoring_run"."slot_count" = "monitoring_run"."question_count" * "monitoring_run"."channel_count" * "monitoring_run"."repeat_count"
    and length("monitoring_run"."region") = 2 and length("monitoring_run"."language") between 2 and 40
    and "monitoring_run"."requested_network_mode" in ('on', 'off', 'unknown')
    and "monitoring_run"."status" in ('queued', 'running', 'paused', 'succeeded', 'partial', 'failed', 'cancelled')
    and "monitoring_run"."sampling_complete" in (0, 1) and "monitoring_run"."customer_payable_minor" = 0
    and (("monitoring_run"."status" in ('queued', 'running', 'paused') and "monitoring_run"."sampling_complete" = 0)
      or "monitoring_run"."status" in ('succeeded', 'partial', 'failed', 'cancelled'))
    and (
      ("monitoring_run"."track" = 'consumer_ui' and "monitoring_run"."currency" is null and "monitoring_run"."upper_minor" is null and "monitoring_run"."estimate_high_minor" is null)
      or ("monitoring_run"."track" = 'model_api' and "monitoring_run"."currency" is not null and length("monitoring_run"."currency") = 3
        and "monitoring_run"."upper_minor" >= 0 and "monitoring_run"."estimate_high_minor" = "monitoring_run"."upper_minor" * "monitoring_run"."slot_count")
    ))
);

CREATE UNIQUE INDEX `monitoring_run_operation_uidx` ON `monitoring_run` (`brand_id`,`operation_id`);
CREATE INDEX `monitoring_run_operation_idx` ON `monitoring_run` (`operation_id`);
CREATE INDEX `monitoring_run_brand_recent_idx` ON `monitoring_run` (`brand_id`,`created_at`,`id`);
CREATE TABLE `monitoring_slot` (
	`id` text PRIMARY KEY NOT NULL,
	`run_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`question_id` text NOT NULL,
	`natural_question` integer NOT NULL,
	`channel_id` text NOT NULL,
	`channel_version` integer NOT NULL,
	`repeat_index` integer NOT NULL,
	`reservation_id` text,
	`status` text NOT NULL,
	`created_at` text NOT NULL,
	`adopted_attempt_id` text,
	`late` integer DEFAULT 0 NOT NULL,
	FOREIGN KEY (`run_id`) REFERENCES `monitoring_run`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "monitoring_slot_state_check" CHECK("monitoring_slot"."natural_question" in (0, 1) and "monitoring_slot"."repeat_index" between 1 and 3
    and "monitoring_slot"."channel_version" > 0 and "monitoring_slot"."late" in (0, 1)
    and "monitoring_slot"."status" in ('queued', 'running', 'paused', 'succeeded', 'failed', 'cancelled', 'reconciliation_required')
    and (("monitoring_slot"."status" = 'succeeded' and "monitoring_slot"."adopted_attempt_id" is not null)
      or ("monitoring_slot"."status" <> 'succeeded' and "monitoring_slot"."adopted_attempt_id" is null)))
);

CREATE UNIQUE INDEX `monitoring_slot_position_uidx` ON `monitoring_slot` (`run_id`,`question_id`,`channel_id`,`repeat_index`);
CREATE INDEX `monitoring_slot_brand_idx` ON `monitoring_slot` (`brand_id`,`run_id`);
CREATE INDEX `monitoring_slot_reservation_idx` ON `monitoring_slot` (`brand_id`,`reservation_id`);
CREATE TABLE `answer_analysis_draft` (
	`id` text PRIMARY KEY NOT NULL,
	`observation_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`mentioned` text NOT NULL,
	`recommended` text NOT NULL,
	`official_site_cited` text NOT NULL,
	`status` text NOT NULL,
	`model_name` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`observation_id`) REFERENCES `answer_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "answer_analysis_draft_state_check" CHECK("answer_analysis_draft"."mentioned" in ('true', 'false', 'unknown')
    and "answer_analysis_draft"."recommended" in ('true', 'false', 'unknown')
    and "answer_analysis_draft"."official_site_cited" in ('true', 'false', 'unknown')
    and "answer_analysis_draft"."status" in ('draft', 'applied', 'dismissed')
    and length("answer_analysis_draft"."model_name") between 1 and 128
    and length("answer_analysis_draft"."owner_id") between 1 and 128
    and length("answer_analysis_draft"."created_at") between 20 and 40)
);

CREATE INDEX `answer_analysis_draft_observation_idx` ON `answer_analysis_draft` (`observation_id`,`created_at`);
CREATE TABLE `answer_analysis_version` (
	`id` text PRIMARY KEY NOT NULL,
	`observation_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`version` integer NOT NULL,
	`entity_version` integer NOT NULL,
	`rule_version` text NOT NULL,
	`mentioned` text NOT NULL,
	`recommended` text NOT NULL,
	`official_site_cited` text NOT NULL,
	`evidence_span` text,
	`status` text NOT NULL,
	`revised_from` text,
	`reason` text,
	`reviewer_id` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`observation_id`) REFERENCES `answer_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "answer_analysis_state_check" CHECK("answer_analysis_version"."version" > 0 and "answer_analysis_version"."entity_version" > 0
    and "answer_analysis_version"."mentioned" in ('true', 'false', 'unknown')
    and "answer_analysis_version"."recommended" in ('true', 'false', 'unknown')
    and "answer_analysis_version"."official_site_cited" in ('true', 'false', 'unknown')
    and "answer_analysis_version"."status" in ('pending', 'classified', 'needs_review', 'revised')
    and ("answer_analysis_version"."revised_from" is null or "answer_analysis_version"."revised_from" <> "answer_analysis_version"."id"))
);

CREATE UNIQUE INDEX `answer_analysis_version_uidx` ON `answer_analysis_version` (`observation_id`,`version`);
CREATE INDEX `answer_analysis_brand_idx` ON `answer_analysis_version` (`brand_id`,`observation_id`,`version`);
CREATE TABLE `answer_citation` (
	`id` text PRIMARY KEY NOT NULL,
	`observation_id` text NOT NULL,
	`brand_id` text NOT NULL,
	`raw_url` text NOT NULL,
	`normalized_url` text NOT NULL,
	`citation_origin` text NOT NULL,
	`position_label` text,
	`ownership` text NOT NULL,
	`page_status` text NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`observation_id`) REFERENCES `answer_observation`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "answer_citation_state_check" CHECK("answer_citation"."citation_origin" in ('provider_native', 'consumer_visible', 'search_candidate', 'analyst_found', 'custom_pipeline')
    and "answer_citation"."ownership" in ('owned_domain', 'owned_account', 'competitor', 'third_party', 'unknown')
    and "answer_citation"."page_status" in ('unknown', 'reachable', 'restricted', 'not_applicable'))
);

CREATE INDEX `answer_citation_observation_idx` ON `answer_citation` (`observation_id`,`id`);
CREATE INDEX `answer_citation_brand_idx` ON `answer_citation` (`brand_id`,`observation_id`);
CREATE TABLE `answer_observation` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`slot_id` text,
	`attempt_id` text,
	`source_mode` text NOT NULL,
	`capture_method` text NOT NULL,
	`question_text` text NOT NULL,
	`answer_text` text NOT NULL,
	`fingerprint` text NOT NULL,
	`captured_at` text NOT NULL,
	`region` text NOT NULL,
	`language` text NOT NULL,
	`requested_network_mode` text NOT NULL,
	`entity_version` integer NOT NULL,
	`citation_set_state` text NOT NULL,
	`evidence_state` text NOT NULL,
	`locator_ref` text,
	`collector_id` text,
	`missing_reason` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`slot_id`) REFERENCES `monitoring_slot`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`attempt_id`) REFERENCES `monitoring_attempt`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "answer_observation_state_check" CHECK("answer_observation"."source_mode" in ('model_api', 'consumer_ui')
    and "answer_observation"."capture_method" in ('official_api', 'manual', 'assisted', 'isolated')
    and "answer_observation"."citation_set_state" in ('complete', 'partial', 'unsupported', 'missing')
    and "answer_observation"."evidence_state" in ('draft_evidence', 'complete', 'incomplete', 'contested')
    and "answer_observation"."entity_version" > 0 and length("answer_observation"."fingerprint") = 64
    and length("answer_observation"."region") = 2 and length("answer_observation"."language") between 2 and 40
    and "answer_observation"."requested_network_mode" in ('on', 'off', 'unknown')
    and (
      ("answer_observation"."evidence_state" = 'draft_evidence')
      or ("answer_observation"."evidence_state" in ('complete', 'incomplete', 'contested') and length("answer_observation"."answer_text") > 0)
    )
    and (
      ("answer_observation"."source_mode" = 'consumer_ui' and "answer_observation"."capture_method" in ('manual', 'assisted'))
      or ("answer_observation"."source_mode" = 'model_api' and "answer_observation"."capture_method" in ('official_api', 'isolated', 'assisted'))
    ))
);

CREATE UNIQUE INDEX `answer_observation_slot_uidx` ON `answer_observation` (`slot_id`) WHERE "answer_observation"."slot_id" is not null and "answer_observation"."evidence_state" in ('complete', 'incomplete', 'contested');
CREATE INDEX `answer_observation_brand_idx` ON `answer_observation` (`brand_id`,`created_at`,`id`);
CREATE INDEX `answer_observation_owner_idx` ON `answer_observation` (`owner_id`,`created_at`,`id`);
CREATE TABLE `optimization_action_draft` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`evidence_ids` text NOT NULL,
	`gap_type` text NOT NULL,
	`observed_gap` text NOT NULL,
	`hypothesis` text NOT NULL,
	`assumption_level` text NOT NULL,
	`question_cluster` text NOT NULL,
	`target_page` text NOT NULL,
	`status` text NOT NULL,
	`model_name` text NOT NULL,
	`task_id` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "optimization_action_draft_state_check" CHECK("optimization_action_draft"."gap_type" in ('fact_error', 'name_confusion', 'key_content_missing', 'page_unreadable', 'citation_gap', 'needs_evidence')
    and "optimization_action_draft"."assumption_level" in ('observed_absence', 'verified', 'pending')
    and "optimization_action_draft"."status" in ('draft', 'confirmed', 'dismissed')
    and (
      ("optimization_action_draft"."status" = 'confirmed' and "optimization_action_draft"."task_id" is not null)
      or ("optimization_action_draft"."status" <> 'confirmed' and "optimization_action_draft"."task_id" is null)
    )
    and length("optimization_action_draft"."model_name") between 1 and 128
    and length("optimization_action_draft"."owner_id") between 1 and 128
    and length("optimization_action_draft"."created_at") between 20 and 40
    and length("optimization_action_draft"."evidence_ids") between 38 and 400
    and length("optimization_action_draft"."observed_gap") between 1 and 500
    and length("optimization_action_draft"."hypothesis") between 1 and 500
    and length("optimization_action_draft"."question_cluster") > 0
    and length("optimization_action_draft"."target_page") > 0)
);

CREATE INDEX `optimization_action_draft_owner_idx` ON `optimization_action_draft` (`owner_id`,`brand_id`,`status`,`created_at`,`id`);
CREATE TABLE `optimization_finding` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`gap_type` text NOT NULL,
	`question_cluster` text NOT NULL,
	`target_page` text NOT NULL,
	`observation_id` text,
	`analysis_version_id` text,
	`evidence_summary` text NOT NULL,
	`problem_statement` text NOT NULL,
	`hypothesis` text NOT NULL,
	`assumption_level` text NOT NULL,
	`steps_json` text NOT NULL,
	`completion_criteria` text NOT NULL,
	`retest_method` text NOT NULL,
	`business_importance` integer NOT NULL,
	`estimated_effort` integer NOT NULL,
	`verified_evidence` integer NOT NULL,
	`privacy_risk` integer NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "optimization_finding_state_check" CHECK("optimization_finding"."gap_type" in ('fact_error', 'name_confusion', 'key_content_missing', 'page_unreadable', 'citation_gap', 'needs_evidence')
    and "optimization_finding"."assumption_level" in ('observed_absence', 'verified', 'pending')
    and "optimization_finding"."business_importance" between 1 and 3
    and "optimization_finding"."estimated_effort" between 1 and 5
    and "optimization_finding"."verified_evidence" in (0, 1)
    and "optimization_finding"."privacy_risk" in (0, 1)
    and length("optimization_finding"."question_cluster") > 0
    and length("optimization_finding"."target_page") > 0)
);

CREATE INDEX `optimization_finding_brand_idx` ON `optimization_finding` (`brand_id`,`created_at`,`id`);
CREATE INDEX `optimization_finding_owner_idx` ON `optimization_finding` (`owner_id`,`created_at`,`id`);
CREATE INDEX `optimization_finding_dedupe_idx` ON `optimization_finding` (`brand_id`,`question_cluster`,`target_page`,`gap_type`);
CREATE TABLE `optimization_task` (
	`id` text PRIMARY KEY NOT NULL,
	`brand_id` text NOT NULL,
	`owner_id` text NOT NULL,
	`primary_finding_id` text NOT NULL,
	`gap_type` text NOT NULL,
	`question_cluster` text NOT NULL,
	`target_page` text NOT NULL,
	`title` text NOT NULL,
	`status` text NOT NULL,
	`priority_bucket` text NOT NULL,
	`manual_rank` integer,
	`reorder_reason` text,
	`completion_note` text,
	`dismiss_reason` text,
	`retest_conclusion` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `brand`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`primary_finding_id`) REFERENCES `optimization_finding`(`id`) ON UPDATE no action ON DELETE restrict,
	CONSTRAINT "optimization_task_state_check" CHECK("optimization_task"."gap_type" in ('fact_error', 'name_confusion', 'key_content_missing', 'page_unreadable', 'citation_gap', 'needs_evidence')
    and "optimization_task"."status" in ('todo', 'doing', 'blocked', 'implemented', 'retest_pending', 'closed', 'dismissed')
    and "optimization_task"."priority_bucket" in ('urgent', 'normal')
    and ("optimization_task"."manual_rank" is null or "optimization_task"."manual_rank" > 0)
    and (
      ("optimization_task"."status" = 'dismissed' and "optimization_task"."dismiss_reason" is not null)
      or ("optimization_task"."status" <> 'dismissed')
    )
    and (
      ("optimization_task"."manual_rank" is not null and "optimization_task"."reorder_reason" is not null)
      or ("optimization_task"."manual_rank" is null)
    ))
);

CREATE UNIQUE INDEX `optimization_task_open_dedupe_uidx` ON `optimization_task` (`brand_id`,`question_cluster`,`target_page`,`gap_type`) WHERE "optimization_task"."status" not in ('closed', 'dismissed');
CREATE INDEX `optimization_task_brand_status_idx` ON `optimization_task` (`brand_id`,`status`,`created_at`,`id`);
CREATE INDEX `optimization_task_owner_idx` ON `optimization_task` (`owner_id`,`updated_at`,`id`);
